public static Description description()
{
    // Description shown in the dropdown on message type setup
    return "My little POC class";
}

public boolean validateMessageTypeParameters(OMGMessageTypeTable    _messageTypeTable)
{
    // Place validation of processing parameters (if any) here

    return true;
}

public OMGInboundMessageResponseContract processMessage(OMGInboundMessageTable   _inboundMessage)
{
    OMGInboundMessageResponseContract   responseContract = new OMGInboundMessageResponseContract();
    ;

    // Place your custom processing logic here

    responseContract.parmProcessed(true);   // Indicates if we try to process the message
    responseContract.parmProcessedOk(true); // Indicates if the processing was sucessful
    responseContract.parmResponse("The processing was ok"); // Place any response/error text here
    responseContract.parmProcessingStatus(OMGProcessingStatus::Processed);  // Force a specific processing status

    return responseContract;
}
